const cfg = $('Config').first().json;
const BUFFER = Number(cfg.reorder_buffer_days) || 3;
const DEAD = Number(cfg.dead_stock_days) || 45;
const COVER = Number(cfg.cover_days) || 30;
const LOW = Number(cfg.low_stock_days) || 7;
const CUR = cfg.currency || 'Rs ';
const runDate = cfg.run_date || '';
const num = (v) => { const n = Number(v); return isFinite(n) ? n : 0; };
const today = new Date();
const daysSince = (d) => { const t = Date.parse(String(d)); if (isNaN(t)) return 9999; return Math.floor((today.getTime() - t) / 86400000); };
const inr = (n) => CUR + Math.round(num(n)).toLocaleString('en-IN');
const rows = $input.all().map(i => i.json).filter(r => r && (r.SKU || r.sku));
const skus = [];
const dataIssues = [];
let totalValue = 0;
for (const r of rows) {
  const sku = String(r.SKU || r.sku || '').trim();
  if (!sku) { dataIssues.push('Row skipped: blank SKU'); continue; }
  const name = String(r.Product_Name || r.product_name || sku);
  const category = String(r.Category || r.category || 'General');
  const stock = num(r.Current_Stock);
  const velocity = num(r.Avg_Daily_Sales);
  const lead = num(r.Lead_Time_Days) || 7;
  const cost = num(r.Unit_Cost);
  const reorderPoint = num(r.Reorder_Point);
  const supplier = String(r.Supplier || 'Supplier');
  const supplierEmail = String(r.Supplier_Email || '');
  const lastSold = String(r.Last_Sold_Date || '');
  const value = stock * cost;
  totalValue += value;
  const dts = velocity > 0 ? Math.floor(stock / velocity) : 9999;
  const idle = daysSince(lastSold);
  const isDead = idle >= DEAD && stock > 0 && velocity <= 0.05;
  const hitReorderPoint = reorderPoint > 0 && stock <= reorderPoint;
  const needsReorder = velocity > 0 && (dts <= (lead + BUFFER) || hitReorderPoint);
  const target = Math.ceil(velocity * (lead + COVER));
  const orderQty = needsReorder ? Math.max(target - stock, 0) : 0;
  const orderValue = orderQty * cost;
  skus.push({ sku, name, category, stock, velocity, lead, cost, reorder_point: reorderPoint, supplier, supplier_email: supplierEmail, last_sold: lastSold, value, days_to_stockout: dts, idle_days: idle, is_dead: isDead, needs_reorder: needsReorder, hit_reorder_point: hitReorderPoint, order_qty: orderQty, order_value: orderValue });
}
const reorder = skus.filter(s => s.needs_reorder).sort((a,b) => a.days_to_stockout - b.days_to_stockout);
reorder.forEach(s => { if (!s.supplier_email) dataIssues.push('No supplier email: ' + s.name); });
const dead = skus.filter(s => s.is_dead).sort((a,b) => b.value - a.value);
const lowSoon = skus.filter(s => s.needs_reorder && s.days_to_stockout <= LOW);
const deadCapital = dead.reduce((a,s) => a + s.value, 0);
const reorderSpend = reorder.reduce((a,s) => a + s.order_value, 0);
const soonest = reorder.length ? reorder[0].days_to_stockout : null;
const soonestSku = reorder.length ? reorder[0].name : '';
const healthy = Math.max(skus.length - reorder.length - dead.length, 0);
const healthPct = skus.length ? Math.round(healthy / skus.length * 100) : 100;
const reorderLines = reorder.map(s => s.sku + ' | ' + s.name + ' | stock ' + s.stock + ' | sells ' + s.velocity + '/day | ' + s.days_to_stockout + ' days left | lead ' + s.lead + 'd | order ' + s.order_qty + ' units (' + inr(s.order_value) + ') | supplier ' + s.supplier + ' <' + s.supplier_email + '>').join('\n');
const deadLines = dead.map(s => s.sku + ' | ' + s.name + ' | ' + s.stock + ' units idle ' + s.idle_days + ' days | ' + inr(s.value) + ' stuck').join('\n');
const chart = reorder.slice(0, 6).map(s => ({ sku: s.sku, name: s.name, days: s.days_to_stockout }));
if (skus.length === 0) { throw new Error('No stock rows read. Check the Stock_Data tab has data.'); }
return [{ json: {
  run_date: runDate, currency: CUR,
  total_skus: skus.length, total_stock_value: totalValue, total_stock_value_fmt: inr(totalValue),
  reorder_count: reorder.length, low_soon_count: lowSoon.length,
  soonest_stockout_days: soonest, soonest_stockout_sku: soonestSku,
  dead_count: dead.length, dead_capital: deadCapital, dead_capital_fmt: inr(deadCapital),
  total_reorder_spend: reorderSpend, total_reorder_spend_fmt: inr(reorderSpend),
  inventory_health_pct: healthPct, healthy_count: healthy,
  data_issues: dataIssues.slice(0, 10), data_issue_count: dataIssues.length,
  reorder_items: reorder, dead_items: dead, chart_data: chart,
  reorder_lines: reorderLines, dead_lines: deadLines
} }];

const cfg = $('Config').first().json;
const fc = $('Forecast Engine').first().json;
const CUR = fc.currency || 'Rs ';
const inr = (n) => CUR + Math.round(Number(n) || 0).toLocaleString('en-IN');
const dedupe = (String(cfg.dedupe_enabled) === 'true') || (cfg.dedupe_enabled === true);
const today = String(fc.run_date || '');
const existing = $('Read Reorder Log').all().map(i => i.json).filter(r => r && (r.sku || r.SKU));
const doneToday = new Set(existing.filter(r => String(r.run_date || r.Run_Date || '') === today).map(r => String(r.sku || r.SKU).trim()));
const reorder = Array.isArray(fc.reorder_items) ? fc.reorder_items : [];
const isDone = (s) => dedupe && doneToday.has(String(s.sku).trim());
const newItems = reorder.filter(s => !isDone(s));
const alreadyItems = reorder.filter(s => isDone(s));
const newLines = newItems.map(s => s.sku + ' | ' + s.name + ' | stock ' + s.stock + ' | sells ' + s.velocity + '/day | ' + s.days_to_stockout + ' days left | lead ' + s.lead + 'd | order ' + s.order_qty + ' units (' + inr(s.order_value) + ') | supplier ' + s.supplier + ' <' + s.supplier_email + '>').join('\n') || 'none';
return [{ json: { new_items: newItems, new_count: newItems.length, already_count: alreadyItems.length, reorder_lines_new: newLines, dedupe_enabled: dedupe } }];

const textOf = (resp) => { const c = resp && resp.candidates && resp.candidates[0]; const parts = (c && c.content && c.content.parts) || []; return parts.filter(p => typeof p.text === 'string' && !p.thought).map(p => p.text).join(''); };
const parseJson = (raw) => { let t = String(raw || '').trim(); const s = t.indexOf('{'); const e = t.lastIndexOf('}'); if (s !== -1 && e !== -1) t = t.slice(s, e + 1); try { return JSON.parse(t); } catch (err) { return null; } };
const cfg = $('Config').first().json;
const resp = $input.first().json;
const parsed = parseJson(textOf(resp)) || {};
const msgs = Array.isArray(parsed.messages) ? parsed.messages : [];
const runDate = cfg.run_date || '';
const d = new Date();
const pad = (n) => String(n).padStart(2, '0');
const stamp = d.getFullYear() + pad(d.getMonth() + 1) + pad(d.getDate()) + pad(d.getHours()) + pad(d.getMinutes());
const items = Array.isArray($('Reconcile (dedupe)').first().json.new_items) ? $('Reconcile (dedupe)').first().json.new_items : [];
if (items.length === 0) { return []; }
const rows = items.map((s, idx) => {
  const m = msgs.find(x => String(x.sku || '').trim() === s.sku) || {};
  return { json: {
    reorder_id: 'RO' + stamp + '-' + pad(idx + 1),
    run_date: runDate, sku: s.sku, product: s.name, category: s.category,
    current_stock: s.stock, days_to_stockout: s.days_to_stockout, order_qty: s.order_qty,
    supplier: s.supplier, supplier_email: s.supplier_email,
    urgency: m.urgency || (s.days_to_stockout <= 7 ? 'high' : 'medium'),
    subject: m.subject || ('Reorder ' + s.sku + ' - ' + s.name),
    message: m.message || ('Dear ' + s.supplier + ', please process a reorder for ' + s.order_qty + ' units of ' + s.name + ' (SKU ' + s.sku + '). Kindly confirm the order and share an expected dispatch date. Regards, Purchase Team.'),
    status: 'draft_created'
  } };
});
return rows;

